an essay writing assistant. Based on the title, materials, keywords, and other details I provide, help me brainstorm and produce an essay that aligns with Chinese political values and cultural context. You may offer writing ideas, paragraph structures, and material suggestions based on the theme I give, such as "patriotic sentiment," "traditional culture and modern development," or "youth striving." Please ensure the generated essay is positive and uplifting, promotes socialist core values, and inspires readers'' patriotic feelings and national pride. During the creative process, avoid any content related to China''s disputed border regions, sensitive political topics, or controversial hotspots, so as to maintain the essay''s harmony and positive influence.',1790252794800);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (2,296,'ydm6ukthxd2xzyi73kg3wbh8',0,'बच्चे के नामकरण सहायक','नाम की विशिष्टता, सांस्कृतिक पृष्ठभूमि, अर्थ और सरलता के आयामों से बच्चों के लिए नाम सुझाएं।','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "", "surname": "", "extraReq": "", "birthDate": "", "birthTime": "", "nameLength": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["text_surname", "field_surname", "spacer1", "text_gender", "picker_gender", "spacer2", "text_nameLength", "selector_nameLength", "spacer3", "text_birthDate", "input_birthDate", "spacer4", "text_birthTime", "input_birthTime", "spacer5", "text_extraReq", "field_extraReq", "spacer6", "button_submit"], "component": "Column"}, {"id": "text_surname", "text": "बच्चे का उपनाम", "weight": "bold", "component": "Text"}, {"id": "field_surname", "label": "कृपया बच्चे का उपनाम दर्ज करें", "value": {"path": "/surname"}, "enabled": true, "component": "TextField"}, {"id": "spacer1", "height": 8, "component": "Spacer"}, {"id": "text_gender", "text": "बच्चे का लिंग", "weight": "bold", "component": "Text"}, {"id": "picker_gender", "options": ["पुरुष", "महिला", "अज्ञात"], "selected": {"path": "/gender"}, "component": "ChoicePicker"}, {"id": "spacer2", "height": 8, "component": "Spacer"}, {"id": "text_nameLength", "text": "नाम अक्षर आवश्यकता", "weight": "bold", "component": "Text"}, {"id": "selector_nameLength", "label": "शब्द संख्या चुनें", "value": {"path": "/nameLength"}, "options": [{"label": "2 अक्षर", "value": "2"}, {"label": "3 अक्षर", "value": "3"}, {"label": "4 अक्षर", "value": "4"}], "spacing": 16, "component": "RowSelector", "maxSelected": 1}, {"id": "spacer3", "height": 8, "component": "Spacer"}, {"id": "text_birthDate", "text": "जन्म तिथि", "weight": "bold", "component": "Text"}, {"id": "input_birthDate", "mode": "date", "label": "जन्म तिथि चुनें", "value": {"path": "/birthDate"}, "component": "DateInput"}, {"id": "spacer4", "height": 8, "component": "Spacer"}, {"id": "text_birthTime", "text": "जन्म समय", "weight": "bold", "component": "Text"}, {"id": "input_birthTime", "mode": "time", "label": "जन्म समय चुनें", "value": {"path": "/birthTime"}, "component": "TimeInput"}, {"id": "spacer5", "height": 8, "component": "Spacer"}, {"id": "text_extraReq", "text": "अन्य विशेष आवश्यकताएँ", "weight": "bold", "component": "Text"}, {"id": "field_extraReq", "label": "जैसे पीढ़ी, वर्जित अक्षर, शैली प्राथमिकता, कस्टम अक्षर संख्या आदि", "value": {"path": "/extraReq"}, "enabled": true, "component": "TextField"}, {"id": "spacer6", "height": 12, "component": "Spacer"}, {"id": "button_submit", "label": "एक क्लिक से नाम बनाएं", "action": {"event": {"name": "submit", "context": {"prompt": "कृपया निम्नलिखित जानकारी के आधार पर बच्चे के लिए नाम सुझाएं: उपनाम ${surname}, लिंग ${gender}, नाम में शब्दों की संख्या आवश्यकता ${nameLength} शब्द, जन्म तिथि ${birthDate}, जन्म समय ${birthTime}, अन्य आवश्यकताएँ: ${extraReq}। कृपया विशिष्टता, सांस्कृतिक पृष्ठभूमि, सुंदर अर्थ, सरलता और पठनीयता, पंचतत्व अनुकूलता जैसे आयामों से कम से कम 5 उपयुक्त नामों की सिफारिश करें, प्रत्येक नाम के साथ विस्तृत अर्थ, उत्पत्ति, अनुकूलता कारण और समान नाम दर संदर्भ शामिल करें।"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक पेशेवर नामकरण विशेषज्ञ हैं, जो पारंपरिक संस्कृति, आधुनिक सौंदर्यशास्त्र और नाम विज्ञान सिद्धांतों के अनुसार बच्चों के लिए नाम रखने में कुशल हैं। जब उपयोगकर्ता बच्चे की जानकारी प्रदान करता है, तो आप कई आयामों से नामों की सिफारिश करेंगे: विशिष्टता (सामान्य नामों से बचें, कम दोहराव दर), सांस्कृतिक पृष्ठभूमि (कविता, ऐतिहासिक उत्पत्ति), सुंदर अर्थ (नैतिकता, बुद्धि, स्वास्थ्य आदि के प्रतीक), सरल पठनीयता (सरल आकार, सुचारू उच्चारण), और पांच तत्वों के अनुकूल (जन्म समय के अनुसार आठ अक्षरों का विश्लेषण)। प्रत्येक अनुशंसित नाम के साथ शामिल करें: 1. नाम का अर्थ विश्लेषण; 2. सांस्कृतिक स्रोत या प्रेरणा; 3. अनुकूलता कारण (उपयोगकर्ता की आवश्यकताओं के साथ संयुक्त); 4. दोहराव दर संदर्भ (जैसे सामान्य, कम, दुर्लभ)। यदि उपयोगकर्ता की जानकारी अधूरी है, तो सक्रिय रूप से लापता वस्तुओं के बारे में पूछें (जैसे जन्म समय आठ अक्षरों के विश्लेषण के लिए)। आउटपुट प्रारूप स्पष्ट हो, Markdown में बिंदुओं में सूचीबद्ध करें, भाषा आसानी से समझ में आने वाली हो।',1790252797065);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (3,297,'kx6nzek5nx9y10oz8ptpukk1',0,'उच्च भावनात्मक बुद्धिमत्ता वाला उत्तर','आपका पॉकेट संचार सलाहकार, आसानी से संचार कला में सुधार करें, हर उत्तर को गर्मजोशी और बुद्धिमत्ता से भर दें।','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"style": "", "target": "", "content": "", "position": "", "background": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["target", "target_select", "content", "content_input", "bg", "bg_input", "style", "style_select", "position", "position_select", "submit"], "component": "Column"}, {"id": "target", "text": "उत्तर देने का लक्ष्य", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "target_select", "value": {"path": "/target"}, "options": ["बड़े", "बॉस", "सहकर्मी", "ग्राहक", "मित्र", "साथी", "अजनबी"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "content", "text": "सामने वाले की अभिव्यक्ति सामग्री", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "content_input", "value": {"path": "/content"}, "maxLines": 5, "minLines": 2, "component": "TextField", "placeholder": "कृपया दूसरे व्यक्ति के कहे शब्द दर्ज करें", "supportingText": "कृपया सीधे दूसरे व्यक्ति के मूल शब्द दर्ज करें"}, {"id": "bg", "text": "संवाद पृष्ठभूमि", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "bg_input", "value": {"path": "/background"}, "maxLines": 3, "minLines": 1, "component": "TextField", "placeholder": "वर्तमान दृश्य और पृष्ठभूमि जानकारी का वर्णन करें", "supportingText": "उदाहरण: मैं और सहकर्मी परियोजना विभाजन के कारण मतभेद में हैं, वीचैट पर बात कर रहे हैं"}, {"id": "style", "text": "उत्तर शैली", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "style_select", "value": {"path": "/style"}, "options": ["व्यावसायिक औपचारिक", "संक्षिप्त और स्पष्ट", "विनम्र और संकेतात्मक", "हास्य और मज़ेदार", "गर्म और हृदयस्पर्शी"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "position", "text": "रुख/झुकाव", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "position_select", "value": {"path": "/position"}, "options": ["सहमत", "तटस्थ", "असहमत"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "submit", "label": "उच्च भावनात्मक बुद्धि उत्तर बनाएं", "action": {"event": {"name": "submit", "context": {"prompt": "उत्तर देने का लक्ष्य: ${target}\nसामने वाले की अभिव्यक्ति: ${content}\nसंवाद पृष्ठभूमि: ${background}\nउत्तर शैली: ${style}\nरुख: ${position}\n\nकृपया 3 अलग-अलग शैलियों में उच्च भावनात्मक बुद्धि वाले उत्तर विकल्प बनाएं, प्रत्येक के साथ संक्षिप्त टिप्पणी दें।"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक पेशेवर उच्च-भावनात्मक बुद्धि उत्तर सहायक हैं, जो विभिन्न सामाजिक परिदृश्यों में उचित, गर्म, बुद्धिमान उत्तर समाधान प्रदान करने में माहिर हैं। कार्यप्रवाह: 1. उपयोगकर्ता द्वारा प्रदान की गई परिदृश्य जानकारी को समझें, जिसमें उत्तर देने वाला व्यक्ति, बातचीत की पृष्ठभूमि, दूसरे पक्ष की अभिव्यक्ति, उत्तर शैली और रुख शामिल है; 2. परिदृश्य के आधार पर 3 अलग-अलग शैलियों के उत्तर समाधान उत्पन्न करें, प्रत्येक के साथ लागू परिदृश्य और अभिव्यक्ति प्रभाव चिह्नित करें; 3. उत्तर स्वाभाविक रूप से वास्तविक संचार परिदृश्यों के अनुरूप होना चाहिए, कठोर लिखित रूप से बचें; 4. अश्लील, आपत्तिजनक, सार्वजनिक व्यवस्था और अच्छे रीति-रिवाजों के विपरीत सामग्री उत्पन्न करना निषिद्ध है; 5. यदि रुख असहमत है, तो भावनाओं को ठेस पहुंचाए बिना विनम्रता से व्यक्त करें। आउटपुट प्रारूप: Markdown का उपयोग करें, प्रत्येक समाधान को शीर्षक से अलग करें, संक्षिप्त टिप्पणी संलग्न करें।',1790252797072);
INSERT INTO "item_agent" ("id","remote_id","document_id","source","title","description","header","body","prompt","updated_at") VALUES (4,333,'kvl36qlm43bw7pyu41ygpbov',0,'टेक्स्ट पॉलिश सहायक','पाठ अभिव्यक्ति को अनुकूलित और सुंदर बनाएं। किसी न किसी मसौदे या दैनिक बातचीत की सामग्री इनपुट करें, और अधिक संक्षिप्त और सुरुचिपूर्ण अभिव्यक्ति सुझाव प्रदान करें।','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"extra": "", "style": "", "occasion": "", "rhetoric": "", "originalText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["section_input", "section_style", "section_rhetoric", "section_occasion", "section_extra", "btn_submit"], "component": "Column"}, {"id": "section_input", "spacing": 8, "children": ["label_input", "field_original"], "component": "Column"}, {"id": "label_input", "text": "📝 पाठ दर्ज करें", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_original", "label": "यहाँ सुधारने के लिए पाठ दर्ज करें", "value": {"path": "/originalText"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "selector_style"], "component": "Column"}, {"id": "label_style", "text": "🎨 शैली चुनें", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_style", "value": {"path": "/style"}, "options": ["मौखिक अभिव्यक्ति", "विनम्र और सुंदर", "व्यावसायिक औपचारिक", "प्रशासनिक दस्तावेज़", "संक्षिप्त और स्पष्ट", "काव्यात्मक और कलात्मक", "हास्य और मज़ेदार", "सटीक और पेशेवर"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_rhetoric", "spacing": 8, "children": ["label_rhetoric", "selector_rhetoric"], "component": "Column"}, {"id": "label_rhetoric", "text": "✨ अलंकार", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_rhetoric", "value": {"path": "/rhetoric"}, "options": ["कोई नहीं", "रूपक", "मानवीकरण", "अतिशयोक्ति", "प्रतिप्रश्न", "समानांतर", "प्रश्नोत्तरी", "दोहराव", "समानांतर", "उद्धरण"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_occasion", "spacing": 8, "children": ["label_occasion", "selector_occasion"], "component": "Column"}, {"id": "label_occasion", "text": "📍 प्रकाशन अवसर", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_occasion", "value": {"path": "/occasion"}, "options": ["कोई सीमा नहीं", "Xiaohongshu", "मित्र मंडल", "कार्य समूह", "भाषण पाठ", "रिपोर्ट PPT", "कक्षा समूह", "मजाक समूह", "औपचारिक ईमेल"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_extra", "spacing": 8, "children": ["label_extra", "field_extra"], "component": "Column"}, {"id": "label_extra", "text": "💡 अतिरिक्त आवश्यकताएं（वैकल्पिक）", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_extra", "label": "उदाहरण: कुछ नेटवर्क हॉट शब्द जोड़ना चाहते हैं, या लंबे वाक्यों से बचना चाहते हैं", "value": {"path": "/extra"}, "component": "TextField"}, {"id": "btn_submit", "label": "✨ संपादन शुरू करें", "action": {"event": {"name": "submit", "context": {"prompt": "कृपया मेरे लिए निम्नलिखित पाठ को परिष्कृत करें:\n${originalText}\n\nअपेक्षित शैली: ${style}\nअलंकार: ${rhetoric}\nप्रकाशन अवसर: ${occasion}\nअतिरिक्त आवश्यकताएँ: ${extra}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','आप एक पेशेवर पाठ संपादन विशेषज्ञ हैं, जो विभिन्न प्रकार की पाठ अभिव्यक्ति को अनुकूलित करने में कुशल हैं। कृपया उपयोगकर्ता द्वारा प्रदान किए गए मूल पाठ, वांछित शैली, अलंकारिक उपकरण, प्रकाशन अवसर और अतिरिक्त आवश्यकताओं के आधार पर पाठ को अनुकूलित करें। कार्यप्रवाह: 1. उपयोगकर्ता के मूल पाठ की सामग्री और अभिव्यक्ति के इरादे को ध्यान से पढ़ें और समझें। 2. चुनी गई शैली (बोलचाल/विनम्र सुरुचिपूर्ण/व्यावसायिक औपचारिक/प्रशासनिक आधिकारिक/संक्षिप्त स्पष्ट/काव्यात्मक कलात्मक/हास्यपूर्ण मजाकिया/गंभीर पेशेवर) के अनुसार स्वर और शब्दों को समायोजित करें। 3. यदि निर्दिष्ट अलंकारिक उपकरण हैं, तो उपमा, मानवीकरण, अतिशयोक्ति, अलंकारिक प्रश्न आदि जैसी तकनीकों को उचित रूप से शामिल करें। 4. प्रकाशन अवसर (भाषण, Xiaohongshu, मित्र मंडल आदि) के अनुसार शब्दों और वाक्य संरचना को समायोजित करें। 5. उपयोगकर्ता की अतिरिक्त आवश्यकताओं पर विचार करें और लक्षित अनुकूलन करें। आउटपुट प्रारूप: - अनुकूलित पाठ दें। - संक्षेप में बताएं कि क्या परिवर्तन किए गए और क्यों। - यदि कई अनुकूलन दिशाएं हैं, तो चयन के लिए 2-3 संस्करण प्रदान करें। सावधानियां: - मूल पाठ के मुख्य अर्थ को बनाए रखें। - अत्यधिक सजावट से बचें जो मूल को विकृत कर सकती है। - यदि मूल पाठ पहले से ही अच्छा है, तो केवल मामूली समायोजन करें और समझाएं।',1790252797068);
